  RoomGame game=RoomGame();bool started=false,paused=false,audio=false;final watch=Stopwatch();double previousSeconds=0;Timer? animation;Timer? clock;String session=newSession(),message='激活信号节点，找齐三枚标记，然后离开房间。';
